def trump_detector(text: str) -> float:
    vowels = 'aeiou'
    total_vowels = 0
    extra_vowels = 0
    i = 0
    while i < len(text):
        if text[i].lower() in vowels:
            total_vowels += 1
            count = 1
            while i + 1 < len(text) and text[i].lower() == text[i + 1].lower():
                count += 1
                i += 1
            if count > 1:
                extra_vowels += count - 1
        i += 1
    trump_score = extra_vowels / total_vowels if total_vowels > 0 else 0
    return round(trump_score, 2)
